using NaughtyAttributes;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class DiceBagDiscardButton : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private Button button;

	[SerializeField]
	private PlayerDiceInventoryData dicePool;

	[SerializeField]
	private GameObject counterText;

	[Header("Player Data")]
	[SerializeField]
	private bool customSpritePerCharacter;

	[SerializeField]
	[ShowIf("customSpritePerCharacter")]
	private Image buttonImage;

	private void Awake()
	{
		if (customSpritePerCharacter && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.EnableSprite)
		{
			buttonImage.sprite = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.AstrariumSprite;
			buttonImage.transform.position += ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.AstrariumSpritePositionAdjustment;
		}
	}

	public void DisableIfNoDiceOrNotOnBattle()
	{
		button.interactable = !ReferenceSingleton<GameStateManager>.Instance.CurrentGameStateIsNonBattleState() && dicePool.GetDicesAmount() > 0;
	}

	public void OpenDicePanel()
	{
		if (dicePool.GetDicesAmount() != 0)
		{
			button.onClick.Invoke();
		}
	}

	public void OnTryOpenDrawPoolPanel()
	{
		TryOpenDicePanel();
	}

	public void OnTryOpenDiscardPanel()
	{
		TryOpenDicePanel();
	}

	private void TryOpenDicePanel()
	{
		if (button.interactable)
		{
			button.onClick.Invoke();
		}
	}

	public void OnStartPlayerRewardState()
	{
		counterText.SetActive(value: false);
		button.interactable = false;
	}

	public void OnStartEndOfBattleState()
	{
		counterText.SetActive(value: false);
		button.interactable = false;
	}

	public void OnStartMapState()
	{
		counterText.SetActive(value: false);
		button.interactable = false;
	}

	public void OnEnableDrawPoolAndDiscardCounterText()
	{
		counterText.SetActive(value: true);
	}
}
